pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;
    function setUp() public { 
        deployer = address(this);
        c = new C(address(this), 0, 0, address(this)); 
    }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= 1e30);
        vm.prank(deployer);
        // Do nothing that would change owner; just ensure we can call depositAndStake without revert
        // The rule: owner() must never return address(c) after construction
        assertTrue(c.owner() != address(c));
    }
}

