import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer = address(this);
    address operator;

    function setUp() public { 
        operator = address(123);
        c = new C(operator, address(0), address(0), new address[](0));
    }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0) && caller != operator && caller != deployer);
        vm.assume(amount > 0 && amount < 1e30);

        vm.prank(caller);
        // depositAndStake will revert because isCvxShutdown() is false and clpToken allowance insufficient;
        // but we only care about the owner() value difference if we could call depositAndStake.
        // Since we cannot easily make it succeed in test, we use a different approach.
        // We just call owner() directly and assert the rule.

        // The general rule: owner() returns the deployer (address(this)).
        // This holds for the reference, but the mutant returns msg.sender.
