import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= type(uint128).max); // bound to avoid overflow issues
        c.setOperator(address(this));
        c.setCvxPoolInfo(0, address(0), address(0x123));
        // prank as operator
        vm.prank(address(this));
        // call depositAndStake - will revert if owner() is not correct (mutant returns address(0))
        bool reverted;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Rule: depositAndStake should not revert because we are operator and not shutdown (poolInfo returns shutdown=false by default)
        assertTrue(!reverted);
    }
}

