pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(address attacker, uint256 amount) public {
        amount = bound(amount, 0, 1e30);
        vm.assume(attacker != address(this));

        // Get the operator (should be address(this) initially)
        address op = c.operator();

        // If the caller is not the operator, the call should revert
        bool reverted;
        if (attacker != op) {
            vm.prank(attacker);
            (bool success, ) = address(c).call(abi.encodeWithSignature("depositAndStake(uint256)", amount));
            reverted = !success;
        } else {
            vm.prank(attacker);
            (bool success, ) = address(c).call(abi.encodeWithSignature("depositAndStake(uint256)", amount));
            reverted = !success;
        }

        // The rule: if the caller is not the operator, the call MUST revert
        // The operator is set by the owner, so if owner() returns address(0), operator can never be set properly
        assertTrue(attacker != op ? reverted : true);
    }
}

