pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0, 0, address(this)); }
    function testFuzz_property(uint256 amount) public {
        // Avoid overflow and zero deposits (assume amount > 0)
        vm.assume(amount > 0 && amount < 1e30);
        // Record earned before deposit
        uint256 earnedBefore = c.earned();
        // Perform deposit
        vm.prank(address(this));
        c.depositAndStake(amount);
        // Record earned after deposit
        uint256 earnedAfter = c.earned();
        // The genuine earned() depends on reward pool state, but after depositing nothing changed rewards;
        // the buggy version returns the whole reward token balance, which increases by the deposit amount.
        // The invariant: the difference in earned before/after should NOT equal the deposit amount (since no rewards accrued).
        assertTrue(earnedAfter - earnedBefore != amount, "earned difference should not equal deposit amount");
    }
}

